// OrderDetail.jsx
import React, { useEffect, useState } from "react";
import { Spinner } from "react-bootstrap";
import { getMyOrderDetail } from "../../Services/ApiUserService.jsx";
import { useParams } from "react-router-dom";

// Helpers
const fmtDateTime = (iso) => {
    try {
        const d = new Date(iso);
        const date = d.toLocaleDateString("vi-VN", { day: "2-digit", month: "2-digit", year: "numeric" });
        const time = d.toLocaleTimeString("vi-VN", { hour12: false }).replace(/\.\d+$/, "");
        return `${date} ${time}`;
    } catch {
        return "-";
    }
};
const fmtMoneySigned = (n) => {
    const x = Number(n) || 0;
    return x.toLocaleString("vi-VN", { maximumFractionDigits: 0 }) + " đ";
};

const OrderDetail = () => {
    const { id } = useParams();



    const [detail, setDetail] = useState(null);
    const [loading, setLoading] = useState(false);
    const [err, setErr] = useState("");

    useEffect(() => {
        const fetchOrderDetail = async () => {
            setLoading(true);
            setErr("");
            try {
                const data = await getMyOrderDetail(id);
                setDetail(data);
            }
            catch {
                setErr("Failed to fetch order detail");
                setDetail(null);
            }

        }
        fetchOrderDetail();

    }, [id]);
    if (loading) {
        return (
            <div className="d-flex align-items-center gap-2 p-3">
                <Spinner animation="border" size="sm" />
                <span>Đang tải đơn hàng…</span>
            </div>
        );
    }

    if (err) {
        return (
            <div className="container py-4">
                <div className="alert alert-danger" role="alert">
                    <h4 className="alert-heading">Lỗi!</h4>
                    <p className="mb-3">{error}</p>
                    <button className="btn btn-outline-danger" onClick={() => window.location.reload()}>
                        Thử lại
                    </button>
                </div>
            </div>
        );
    }


    return (
        <div className="container py-4 order-detail">
            <h4 className="fw-bold mb-3">Chi tiết đơn hàng</h4>
            <table className="table table-borderless small">
                <tbody>
                    <tr>
                        <td className="text-secondary">Mã chi tiết</td>
                        <td className="text-end">#{detail.id}</td>
                    </tr>
                    <tr>
                        <td className="text-secondary">Thời gian đặt hàng</td>
                        <td className="text-end">{fmtDateTime(detail.time)}</td>
                    </tr>
                    <tr>
                        <td className="text-secondary">Số lượng</td>
                        <td className="text-end">{detail.quantity}</td>
                    </tr>
                    <tr>
                        <td className="text-secondary">Tổng tiền</td>
                        <td className="text-end fw-semibold text-success">
                            {fmtMoneySigned(detail.total_amount)}
                        </td>
                    </tr>
                    <tr>
                        <td className="text-secondary">Loại sản phẩm</td>
                        <td className="text-end">{detail.type_product_name || `ID: ${detail.type_product_id}`}</td>
                    </tr>
                </tbody>
            </table>

            <h5 className="fw-bold mb-3">Danh sách tài khoản</h5>
            {detail.accounts_info && detail.accounts_info.length > 0 ? (
                <table className="table table-striped">
                    <thead>
                        <tr>
                            <th>ID</th>
                            <th>Tên đăng nhập</th>
                            <th>Mật khẩu</th>
                        </tr>
                    </thead>
                    <tbody>
                        {detail.accounts_info.map((account) => (
                            <tr key={account.id}>
                                <td>{account.id}</td>
                                <td>{account.login_name}</td>
                                <td>{account.password}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            ) : (
                <p>Không có tài khoản nào.</p>
            )}
        </div>
    );
};

export default OrderDetail;
